  "command": "LEAN_BRIDGE_REVIEWED_FIN_WASM_ENTRY_TEST=1 LEAN_BRIDGE_REVIEWED_FIN_WASM_ENTRY_BROWSER_TEST=1 LEAN_BRIDGE_TYPE_CORPUS_BROWSERS=chromium,firefox,webkit node --test --test-concurrency=1 --test-name-pattern='^probe ordinary scalar Fin entry is accounted in installed npm packages$' tests/reviewed-fin-wasm-entry.test.mjs",
